  ('215c32fb-609d-485c-9a99-2aad81a3e6c6', 'SS-0430', 'تول مطرز بلمعة ترتر بنقشة ورود – رمادي', 'تطريز دانتيل بارز بلون واحد هادئ. اللون: رمادي. القاعدة تول شفاف ناعم يُفصَّل عادةً على بطانة، والزخرفة تطريز وترتر. مناسب لفساتين السهرة والمناسبات، ويُستخدم للفستان كاملاً أو للصدر والأكمام مع قماش سادة. يمكنك شراؤه وحده، أو تفصيله في مشغل ياسمين الشام بالخبر.', array['سهرة', 'خطوبة', 'ملكة']::text[], array['تول', 'تطريز', 'ترتر']::text[]),
  ('80f450ff-4aa1-4b6b-948a-7d3ec60831ac', 'SS-0425', 'تول مشغول بالخرز والترتر بنقشة أغصان – أخضر', 'أغصان مشغولة بالخرز اللامع تغطي القماش. اللون: أخضر. القاعدة تول شفاف ناعم يُفصَّل عادةً على بطانة، والزخرفة تطريز وخرز وترتر. قماش فاخر يليق بفساتين الخطوبة والملكة والمناسبات الكبيرة، ويكفي وحده لإبراز الفستان دون إضافات. يمكنك شراؤه وحده، أو تفصيله في مشغل ياسمين الشام بالخبر.', array['سهرة', 'خطوبة', 'ملكة']::text[], array['تول', 'تطريز', 'خرز', 'ترتر']::text[]),
