  ('cd288385-3873-480d-b8c1-192e703f7517', 'SS-0226', 'دانتيل بنقشة ورود – أحمر', 'دانتيل شانتيلي خفيف بزهور رقيقة وحواف مزخرفة. اللون: أحمر. دانتيل شفاف يُفصَّل عادةً على بطانة، والزخرفة تطريز. خامة ناعمة وهادئة تناسب السهرات والطبقات الخارجية والأكمام. يمكنك شراؤه وحده، أو تفصيله في مشغل ياسمين الشام بالخبر.', array['سهرة']::text[], array['دانتيل', 'تطريز']::text[]),
  ('aa702b08-9067-4ef6-afc8-e9f323328704', 'SS-0398', 'تول مشغول بالخرز والترتر بنقشة تجريدية – أسود', 'كتل هندسية متدرجة مشغولة بالخرز والترتر. اللون: أسود. القاعدة تول شفاف ناعم يُفصَّل عادةً على بطانة، والزخرفة خرز وترتر. قماش فاخر يليق بفساتين الخطوبة والملكة والمناسبات الكبيرة، ويكفي وحده لإبراز الفستان دون إضافات. يمكنك شراؤه وحده، أو تفصيله في مشغل ياسمين الشام بالخبر.', array['سهرة', 'خطوبة', 'ملكة']::text[], array['تول', 'خرز', 'ترتر']::text[]),
