  ('28ce108d-e099-41a4-a830-a969401453eb', 'SS-0046', 'تول بورود بارزة – أسود', 'زهور بارزة وأغصان مطرزة على تول بنفس اللون. اللون: أسود. القاعدة تول شفاف ناعم يُفصَّل عادةً على بطانة، والزخرفة ورود بارزة ثلاثية الأبعاد وتطريز. قماش فاخر يليق بفساتين الخطوبة والملكة والمناسبات الكبيرة، ويكفي وحده لإبراز الفستان دون إضافات. يمكنك شراؤه وحده، أو تفصيله في مشغل ياسمين الشام بالخبر.', array['سهرة', 'خطوبة', 'ملكة']::text[], array['تول', 'ورود بارزة ثلاثية الأبعاد', 'تطريز']::text[]),
  ('0d1591c8-c25d-4dfb-9123-c54a76b438da', 'SS-0047', 'تول مطرز بلمعة ترتر بنقشة أغصان – أبيض', 'أغصان مطرزة ناعمة بلون واحد. اللون: أبيض. القاعدة تول شفاف ناعم يُفصَّل عادةً على بطانة، والزخرفة تطريز وترتر. مناسب لفساتين السهرة والمناسبات، ويُستخدم للفستان كاملاً أو للصدر والأكمام مع قماش سادة. يمكنك شراؤه وحده، أو تفصيله في مشغل ياسمين الشام بالخبر.', array['سهرة', 'خطوبة', 'ملكة']::text[], array['تول', 'تطريز', 'ترتر']::text[]),
