  ('f2561030-60f7-4a59-95da-91404ba4e86f', 'SS-0021', 'دانتيل بلمعة ترتر بنقشة ورود – أسود', 'دانتيل زهور كثيف بلمعة ترتر. اللون: أسود. دانتيل شفاف يُفصَّل عادةً على بطانة، والزخرفة تطريز وترتر. مناسب لفساتين السهرة والمناسبات، ويُستخدم للفستان كاملاً أو للصدر والأكمام مع قماش سادة. يمكنك شراؤه وحده، أو تفصيله في مشغل ياسمين الشام بالخبر.', array['سهرة', 'خطوبة', 'ملكة']::text[], array['دانتيل', 'تطريز', 'ترتر']::text[]),
