  ('552cd0fe-6689-4cd1-a7d6-65f0cf3bbb05', 'SS-0013', 'تول بالكريستال بنقشة هندسية – وردي', 'شبكة معينات رفيعة مع حبات كريستال. اللون: وردي. القاعدة تول شفاف ناعم يُفصَّل عادةً على بطانة، والزخرفة ترتر وكريستال. مناسب لفساتين السهرة والمناسبات، ويُستخدم للفستان كاملاً أو للصدر والأكمام مع قماش سادة. يمكنك شراؤه وحده، أو تفصيله في مشغل ياسمين الشام بالخبر.', array['سهرة', 'خطوبة', 'ملكة']::text[], array['تول', 'ترتر', 'كريستال']::text[]),
  ('221b9127-ca5d-4354-bd5a-e7c0d0ae4c2a', 'SS-0012', 'تول بالترتر بنقشة تجريدية – ذهبي', 'ترتر لامع بنقشة شبكية. اللون: ذهبي. القاعدة تول شفاف ناعم يُفصَّل عادةً على بطانة، والزخرفة ترتر. قماش فاخر يليق بفساتين الخطوبة والملكة والمناسبات الكبيرة، ويكفي وحده لإبراز الفستان دون إضافات. يمكنك شراؤه وحده، أو تفصيله في مشغل ياسمين الشام بالخبر.', array['سهرة', 'خطوبة', 'ملكة']::text[], array['تول', 'ترتر']::text[]),
  ('5c232864-16ef-4635-a0b3-ecc956f57212', 'SS-0011', 'مخمل محروق بنقشة ورود – كحلي', 'مخمل محروق بورود وأغصان على أرضية شفافة. اللون: كحلي. مخمل محروق (ديفوريه): نقشة مخملية على أرضية شفافة تعطي عمقاً وملمساً ناعماً. يناسب فساتين السهرة والجلابيات الفاخرة في المواسم الباردة. يمكنك شراؤه وحده، أو تفصيله في مشغل ياسمين الشام بالخبر.', array['سهرة', 'خطوبة', 'ملكة']::text[], array['مخمل محروق']::text[]),
  ('29587c47-a2c2-4014-9b38-7fd07ccef34e', 'SS-0010', 'مخمل محروق بخيوط لامعة بنقشة تجريدية – أسود', 'مخمل محروق بنقشة رخامية مع خطوط ذهبية. اللون: أسود. مخمل محروق (ديفوريه): نقشة مخملية على أرضية شفافة تعطي عمقاً وملمساً ناعماً، والزخرفة خيوط لامعة. يناسب فساتين السهرة والجلابيات الفاخرة في المواسم الباردة. يمكنك شراؤه وحده، أو تفصيله في مشغل ياسمين الشام بالخبر.', array['سهرة', 'خطوبة', 'ملكة']::text[], array['مخمل محروق', 'خيوط لامعة']::text[]),
