  ('854b3d99-1600-4f79-891a-0c2c3f3769e0', 'SS-0004', 'تول بالترتر', 'ترتر لامع منثور على تول بلون قوي. القاعدة تول شفاف ناعم يُفصَّل عادةً على بطانة، والزخرفة ترتر. مناسب لفساتين السهرة والمناسبات، ويُستخدم للفستان كاملاً أو للصدر والأكمام مع قماش سادة. يمكنك شراؤه وحده، أو تفصيله في مشغل ياسمين الشام بالخبر.', array['سهرة', 'خطوبة', 'ملكة']::text[], array['تول', 'ترتر']::text[]),
  ('e06e20cd-a82e-4a99-87d8-cd8cfbc97002', 'SS-0005', 'دانتيل بنقشة ورود – كحلي', 'دانتيل شانتيلي ناعم بلون داكن. اللون: كحلي. دانتيل شفاف يُفصَّل عادةً على بطانة، والزخرفة تطريز. خامة ناعمة وهادئة تناسب السهرات والطبقات الخارجية والأكمام. يمكنك شراؤه وحده، أو تفصيله في مشغل ياسمين الشام بالخبر.', array['سهرة']::text[], array['دانتيل', 'تطريز']::text[]),
  ('cdd65316-b84b-4e9f-a969-9f95993fce99', 'SS-0002', 'تول بورود بارزة – تفاحي', 'زهور بارزة ثلاثية الأبعاد مع خرز وترتر. اللون: تفاحي. القاعدة تول شفاف ناعم يُفصَّل عادةً على بطانة، والزخرفة ورود بارزة ثلاثية الأبعاد وترتر وخرز. قماش فاخر يليق بفساتين الخطوبة والملكة والمناسبات الكبيرة، ويكفي وحده لإبراز الفستان دون إضافات. يمكنك شراؤه وحده، أو تفصيله في مشغل ياسمين الشام بالخبر.', array['سهرة', 'خطوبة', 'ملكة']::text[], array['تول', 'ورود بارزة ثلاثية الأبعاد', 'ترتر', 'خرز']::text[]),
  ('551fdd7e-6376-459d-bce3-9044f3cb2460', 'SS-0001', 'تول مطرز بلمعة ترتر بنقشة ورود – زيتي', 'زهور مطرزة بلونين على تول ناعم. اللون: زيتي. القاعدة تول شفاف ناعم يُفصَّل عادةً على بطانة، والزخرفة تطريز وترتر. مناسب لفساتين السهرة والمناسبات، ويُستخدم للفستان كاملاً أو للصدر والأكمام مع قماش سادة. يمكنك شراؤه وحده، أو تفصيله في مشغل ياسمين الشام بالخبر.', array['سهرة', 'خطوبة', 'ملكة']::text[], array['تول', 'تطريز', 'ترتر']::text[])
)
update public.fabrics f
set name = v.name,
    description = v.description,
    occasions = v.occasions,
    tags = v.tags,
    updated_at = now()
from v
where f.id = v.id::uuid
  and f.fabric_code = v.code
  and (f.name is null or btrim(f.name) = '');

commit;

